OUT = ROOT / 'docs'
OUT.mkdir(exist_ok=True)
pdfmetrics.registerFont(TTFont('Body', 'C:/Windows/Fonts/arial.ttf'))
pdfmetrics.registerFont(TTFont('BodyBold', 'C:/Windows/Fonts/arialbd.ttf'))
pdfmetrics.registerFontFamily('Body', normal='Body', bold='BodyBold', italic='Body', boldItalic='BodyBold')
styles = getSampleStyleSheet()
styles.add(ParagraphStyle(name='TitleL',fontName='BodyBold',fontSize=24,leading=29,textColor=colors.HexColor('#414d3c'),spaceAfter=13))
styles.add(ParagraphStyle(name='SubL',fontName='BodyBold',fontSize=11,leading=15,spaceBefore=12,spaceAfter=7,textColor=colors.HexColor('#414d3c')))
styles.add(ParagraphStyle(name='BodyL',fontName='Body',fontSize=9,leading=13,spaceAfter=8,textColor=colors.HexColor('#45483f')))
styles.add(ParagraphStyle(name='SmallL',fontName='Body',fontSize=8,leading=11,spaceAfter=6,textColor=colors.HexColor('#5f6857')))
styles.add(ParagraphStyle(name='CellL',fontName='Body',fontSize=8,leading=11,textColor=colors.HexColor('#45483f')))
def p(text,style='BodyL'): return Paragraph(text,styles[style])
def heading(text): return p(text,'SubL')
story=[p('Lumea / Trackingkonzept','TitleL'),p('TEIL D · PROBEARBEIT · STAND 22.10.2026','SmallL'),p('Ziel: den Weg vom Produktaufruf bis zum ersten Abo-Abschluss nachvollziehen. Meta-Pixel <b>1234567890</b> und GA4 <b>G-LUMEA0000</b> (vorgegebene Platzhalter). Kein echtes Werbekonto, kein echter Verkauf. Die Demo löst Standardereignisse mit den vorgesehenen Bestellwerten aus; diese sind keine realen Umsätze.')]
story+=[heading('1. Ereignisse und Auslöser')]
rows=[['Ereignis','Wann / warum','Parameter'],
['PageView<br/>GA4: page_view','Einmal pro Dokument auf /, /bestellung und /danke nach Einwilligung. Misst Seitenaufrufe, keine Anker-Klicks.','Keine zusätzlichen Geschäftsdaten.'],
['ViewContent<br/>GA4: view_item','Produktseite / nach Einwilligung. Produktinteresse im Funnel.','content_ids: ["LUMEA-30"]\ncontent_type: "product"\nvalue: 14.5; currency: "EUR"'],
['AddToCart<br/>GA4: add_to_cart','CTA öffnet den Warenkorb. Ein Ereignis pro Öffnung; reines Rendern oder andere Dialoge zählen nicht.','Wie ViewContent, zusätzlich num_items: 1.'],
['InitiateCheckout<br/>GA4: begin_checkout','Bestellseite /bestellung wird aufgerufen. Misst den Einstieg in die Bestellstrecke.','Wie ViewContent, zusätzlich num_items: 1.'],
['AddPaymentInfo<br/>GA4: add_payment_info','Gültige Lieferangaben und gewählte Demo-Zahlungsart werden mit "Bestellung prüfen" bestätigt.','Wie ViewContent, zusätzlich num_items: 1. Keine Zahlungsart, Karten- oder Kontodaten.'],
['Purchase<br/>GA4: purchase','Nur /danke nach erfolgreich abgeschlossener Demo-Bestellung und Einwilligung zum Abschlusszeitpunkt. Primäres Conversion-Ereignis.','value: 14.5; currency: "EUR"\ncontent_ids: ["LUMEA-30"]\ncontent_type: "product"\nnum_items: 1.']]
tab=Table([[p(c.replace('\n','<br/>'),'CellL') for c in row] for row in rows],colWidths=[84,224,193],hAlign='LEFT')
tab.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#eef1e9')),('FONTNAME',(0,0),(-1,0),'BodyBold'),('VALIGN',(0,0),(-1,-1),'TOP'),('TOPPADDING',(0,0),(-1,-1),9),('BOTTOMPADDING',(0,0),(-1,-1),9),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('LINEBELOW',(0,0),(-1,-1),.4,colors.HexColor('#dce2d5'))]))
story += [tab,p('GA4 ergänzt currency, value und items (item_id LUMEA-30, price 14.5, quantity 1). Purchase enthält transaction_id=Demo-Bestell-ID und shipping=0. Der Data Layer verwendet GA4-Ereignisnamen; ecommerce wird vor jedem Ereignis zurückgesetzt. GTM-LUMEA0000 ist ein nicht veröffentlichter Demo-Platzhalter: GA4 läuft direkt über gtag.js. Mit echter GTM-ID wird der Direktmodus abgeschaltet; Importvorlage: docs/gtm-container.json.','SmallL'),heading('2. Wert und Zähllogik'),p('Der erste Monat kostet <b>14,50 EUR inkl. MwSt. und Versand</b>. Deshalb beträgt der Purchase-Wert 14.5 und nicht 29 EUR oder ein angenommener Lifetime Value. Ein separates Subscribe-Ereignis entfällt, damit derselbe Abschluss nicht als zweite Conversion gezählt wird.'),p('Jedes Ereignis erhält eventID. Purchase verwendet purchase-&lt;zufällige Demo-Bestell-ID&gt;. Der Sitzungsdatensatz speichert purchaseSent: Ein Reload der Dankeseite sendet keinen zweiten Purchase. Ein direkter Besuch ohne Bestellung sendet keinen Purchase. Ein neuer Seitenaufruf darf hingegen einen neuen PageView erzeugen.','SmallL'),PageBreak()]
story += [p('Einwilligung & Prüfung','TitleL'),heading('3. Einwilligung vor dem ersten Netzwerkkontakt'),p('Der Banner bietet "Nur notwendige", "Alle erlauben" und eine speicherbare Auswahl für Statistik (GA4) und Marketing (Meta). Beide Kategorien sind getrennt und zunächst abgewählt. Ohne passende Zustimmung werden weder Meta- noch Google-Skripte geladen und keine Events oder cookieless Pings gesendet. Consent Mode v2 (Basic) setzt vor Tags alle vier Analytics-/Werbezustände auf denied; nur analytics_storage wird nach Statistik-Zustimmung granted. Google-Werbezustände bleiben denied. Ablehnen schränkt die Demo-Bestellung nicht ein. Die versionierte Auswahl wird für 180 Tage im localStorage gespeichert; fehlt sie oder ist sie abgelaufen, erscheint der Banner erneut.'),p('Zustimmung lädt ausschließlich die jeweils erlaubten Original-SDKs und aktiviert die Messung auf der aktuellen Commerce-Seite. Eine alte reine Meta-Einwilligung gilt nicht für Google; die neue Auswahl ist versioniert. Frühere Aktionen werden nicht nachgesendet. Ein ohne passende Einwilligung abgeschlossener Kauf wird bei späterer Zustimmung nicht rückwirkend an den jeweiligen Empfänger gesendet. Kaufmarker sind pro Empfänger getrennt. Cookie-Einstellungen bleiben im Footer erreichbar.'),p('Widerruf sperrt den jeweiligen Dienst (Meta consent revoke; Google consent update und ga-disable) und entfernt zugängliche _fbp-, _fbc- bzw. _ga-Cookies. Vor dem Laden gepufferte SDK-Aufrufe werden verworfen. Bereits gesendete Daten und ein schon geladenes Skript lassen sich nicht zurückholen.'),heading('4. Datenminimierung und sensible Inhalte'),p('Nur feste Produkt-ID, Anzahl, Währung und Preis werden übergeben. Kein Advanced Matching, keine Formulardaten, keine Symptome, kein Alter und keine Medikamentenangaben. Meta-autoConfig, Google Signals und Anzeigenpersonalisierung sind deaktiviert. Der Ratgeber lädt keine Tracking-SDKs. In einer echten GA4-Property zusätzlich Enhanced Measurement deaktivieren (kein Kontozugriff in der Demo). Commerce-URLs werden vor Ereignissen von Fragmenten und freien Query-Parametern bereinigt. Nur ein formal validierter fbclid bleibt für Meta-Klickattribution erhalten; freie UTMs werden entfernt. Referrer-Policy: no-referrer. Meta und Google verarbeiten technisch u. a. IP-Adresse und Browserdaten; Einwilligung ist keine Freigabe für Gesundheitsdaten.'),p('Bestellfelder bleiben ausschließlich im Arbeitsspeicher. sessionStorage enthält nur zufällige Demo-ID, Zeitpunkt, Zahlungsart und Trackingstatus. Keine tatsächliche Zahlungsabwicklung oder Kundenkartei. Vor einem realen Gesundheitsprodukt-Launch müssten Datenklassifizierung, Plattformfreigaben und echte Betreiberangaben gesondert geprüft werden.','SmallL'),heading('5. Monatliche Abbuchungen'),p('Der Browser bestätigt nur den ersten Abo-Abschluss. Es gibt hier keine simulierten Folgemonats-Purchases, Timer oder künstlich hochgerechnete Werte. Im Livebetrieb: bestätigte Zahlungen über signierte Zahlungsanbieter-Webhooks serverseitig verarbeiten, pro Rechnung deduplizieren und Einwilligungs-/Plattformvorgaben beachten. Neue Abos und Verlängerungen getrennt auswerten; Akquisitions-CPA nicht durch wiederkehrende Abbuchungen künstlich verbessern. Keine CAPI im Prototyp.'),heading('6. Live prüfen'),p('1. Frischer Browser: Netzwerkfilter facebook / fbevents / google-analytics / googletagmanager. Vor Zustimmung und nach Ablehnen: keine Meta-Anfragen.<br/>2. Zustimmung: PageView + ViewContent mit Pixel-ID 1234567890.<br/>3. CTA → Warenkorb → Bestellvorschau → gültige Beispieldaten → Prüfung → Demo-Abschluss: AddToCart, InitiateCheckout, AddPaymentInfo, Purchase.<br/>4. Purchase: value=14.5, currency=EUR; einmal trotz Reload. Direkt /danke ohne Bestellung: kein Purchase.<br/>5. Je Kategorie einzeln testen; Widerruf und weitere Navigation: keine weiteren Anfragen abgewählter Dienste. Ohne Marketing funktioniert die Bestellstrecke ebenfalls. Netzwerk-Requests sind der Nachweis; Pixel Helper kann die Platzhalter-ID beanstanden.','SmallL'),p('Technische Referenzen: developers.facebook.com/docs/meta-pixel/implementation/conversion-tracking/ · developers.facebook.com/docs/meta-pixel/implementation/gdpr/ · facebook.com/legal/technology_terms. Meta-Dokumentationsseiten waren am Recherchetag teilweise nur mit Zugriffsbeschränkung erreichbar. Die Implementierung wird zusätzlich anhand tatsächlicher SDK-Netzwerkanfragen geprüft.','SmallL')]
def footer(c,doc):
 c.setFont('Body',8);c.setFillColor(colors.HexColor('#7a8371'));c.drawString(47,25,'Lumea · Technical Marketing Expert · Teil D');c.drawRightString(548,25,str(doc.page))
SimpleDocTemplate(str(OUT/'Teil_D_Tracking.pdf'),pagesize=(595.28,841.89),leftMargin=47,rightMargin=47,topMargin=37,bottomMargin=43,title='Lumea - Trackingkonzept',author='Lumea Probearbeit').build(story,onFirstPage=footer,onLaterPages=footer)
